-- Cineo 0.8: compact workspace, viewing choices and editorial workflows.
create table public.cineo_experience(user_id uuid not null references auth.users(id) on delete cascade,viewer_key text not null,shortcuts text[] not null default '{}',hide_completed boolean not null default false,watch_minutes integer not null default 0 check(watch_minutes between 0 and 1440),orientation text not null default 'auto' check(orientation in ('auto','portrait','landscape')),sensitive_swipe boolean not null default false,revision integer not null default 0,primary key(user_id,viewer_key));
create table public.cineo_library_choices(user_id uuid not null references auth.users(id) on delete cascade,viewer_key text not null,show_id bigint not null references public.cineo_shows(id) on delete cascade,state text not null default 'watching' check(state in ('watching','completed','abandoned')),interested boolean not null default true,hide_resume boolean not null default false,updated_at timestamptz not null default now(),primary key(user_id,viewer_key,show_id));
create index cineo_library_choices_show on public.cineo_library_choices(show_id);
create table public.cineo_bookmarks(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,viewer_key text not null,episode_id bigint not null references public.cineo_episodes(id) on delete cascade,position_ms integer not null check(position_ms between 0 and 14400000),caption text not null default '' check(length(caption)<=100),created_at timestamptz not null default now());
create index cineo_bookmarks_owner on public.cineo_bookmarks(user_id,viewer_key,created_at);
create index cineo_bookmarks_episode on public.cineo_bookmarks(episode_id);
create table public.cineo_show_info(show_id bigint primary key references public.cineo_shows(id) on delete cascade,themes text[] not null default '{}',warnings text[] not null default '{}',lifecycle text not null default 'ongoing' check(lifecycle in ('ongoing','complete','paused')));
create table public.cineo_episode_notes(episode_id bigint primary key references public.cineo_episodes(id) on delete cascade,recap text not null default '' check(length(recap)<=5000));
create table public.cineo_polls(id uuid primary key default gen_random_uuid(),show_id bigint not null references public.cineo_shows(id) on delete cascade,question text not null check(length(question) between 5 and 200),options text[] not null check(cardinality(options) between 2 and 6),closes_at timestamptz not null,created_at timestamptz not null default now());
create index cineo_polls_show on public.cineo_polls(show_id,created_at);
create table public.cineo_poll_votes(poll_id uuid not null references public.cineo_polls(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,viewer_key text not null,choice integer not null check(choice between 0 and 5),primary key(poll_id,user_id,viewer_key));
create index cineo_poll_votes_owner on public.cineo_poll_votes(user_id);
create table public.cineo_receipts(user_id uuid not null references auth.users(id) on delete cascade,viewer_key text not null,event_key text not null check(length(event_key)<=100),created_at timestamptz not null default now(),primary key(user_id,viewer_key,event_key));
create table public.cineo_notices(id uuid primary key default gen_random_uuid(),title text not null check(length(title) between 1 and 100),body text not null check(length(body)<=1000),kind text not null default 'info' check(kind in ('info','maintenance','release')),destination text not null default 'support',starts_at timestamptz not null default now(),ends_at timestamptz not null,active boolean not null default true);
create table public.cineo_surveys(id uuid primary key default gen_random_uuid(),question text not null check(length(question) between 5 and 200),options text[] not null check(cardinality(options) between 2 and 6),active boolean not null default true,created_at timestamptz not null default now());
create table public.cineo_survey_votes(survey_id uuid not null references public.cineo_surveys(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,choice integer not null check(choice between 0 and 5),primary key(survey_id,user_id));
create index cineo_survey_votes_owner on public.cineo_survey_votes(user_id);
create table public.cineo_staff(user_id uuid primary key references auth.users(id) on delete cascade,role text not null check(role in ('reviewer','support')),name text not null check(length(name) between 1 and 60));
create table public.cineo_cases(id uuid primary key default gen_random_uuid(),kind text not null check(kind in ('show','episode','report','appeal','ticket','proposal')),target_id text not null,status text not null default 'open' check(status in ('open','resolved')),assignee uuid references auth.users(id) on delete set null,priority integer not null default 0 check(priority between 0 and 5),created_at timestamptz not null default now(),unique(kind,target_id));
create index cineo_cases_assignee on public.cineo_cases(assignee,status);
create table public.cineo_case_notes(id uuid primary key default gen_random_uuid(),case_id uuid not null references public.cineo_cases(id) on delete cascade,user_id uuid references auth.users(id) on delete set null,body text not null check(length(body) between 1 and 2000),created_at timestamptz not null default now());
create index cineo_case_notes_case on public.cineo_case_notes(case_id,created_at);
create index cineo_case_notes_user on public.cineo_case_notes(user_id);
create table public.cineo_case_actions(id uuid primary key default gen_random_uuid(),case_id uuid not null references public.cineo_cases(id) on delete cascade,user_id uuid references auth.users(id) on delete set null,action text not null,details jsonb not null default '{}',created_at timestamptz not null default now());
create index cineo_case_actions_case on public.cineo_case_actions(case_id,created_at);
create index cineo_case_actions_user on public.cineo_case_actions(user_id);
create table public.cineo_reason_templates(code text primary key,label text not null,body text not null,active boolean not null default true);
insert into public.cineo_reason_templates(code,label,body) values('quality','Qualidade técnica','O arquivo apresenta um problema técnico. Confira o diagnóstico e envie uma versão corrigida.'),('metadata','Informações da produção','Revise o título, a sinopse, a classificação e a identificação dos capítulos.'),('rights','Direitos de distribuição','Precisamos confirmar a autorização para distribuir este conteúdo.'),('content','Conteúdo e classificação','Revise o conteúdo e a classificação indicativa da produção.'),('other','Outros ajustes','Confira os ajustes descritos pela equipe de análise.');
create table public.cineo_revisions(id uuid primary key default gen_random_uuid(),show_id bigint not null references public.cineo_shows(id) on delete cascade,author_id uuid references auth.users(id) on delete set null,content jsonb not null,created_at timestamptz not null default now());
create index cineo_revisions_show on public.cineo_revisions(show_id,created_at);
create index cineo_revisions_author on public.cineo_revisions(author_id);
create table public.cineo_proposals(id uuid primary key default gen_random_uuid(),show_id bigint not null references public.cineo_shows(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,content jsonb not null,status text not null default 'pending' check(status in ('pending','approved','rejected')),reason text not null default '',created_at timestamptz not null default now());
create index cineo_proposals_show on public.cineo_proposals(show_id,created_at);
create index cineo_proposals_user on public.cineo_proposals(user_id);
create table public.cineo_release_news(version integer primary key,title text not null,items jsonb not null default '[]',download_url text not null default '',rollout integer not null default 100 check(rollout between 0 and 100),active boolean not null default true);
create table public.cineo_feature_flags(name text primary key,percentage integer not null default 100 check(percentage between 0 and 100),description text not null default '');
insert into public.cineo_feature_flags(name,description) values('workspace','Novo painel de perfil'),('polls','Enquetes das produções'),('recommendations','Recomendações com preferências do espectador');
create table public.cineo_drafts(user_id uuid not null references auth.users(id) on delete cascade,draft_key text not null check(length(draft_key)<=100),content jsonb not null,revision integer not null default 0,updated_at timestamptz not null default now(),primary key(user_id,draft_key));
create table public.cineo_playback_clock(user_id uuid not null references auth.users(id) on delete cascade,viewer_key text not null,episode_id bigint not null references public.cineo_episodes(id) on delete cascade,observed_at timestamptz not null,primary key(user_id,viewer_key,episode_id));
create index cineo_playback_clock_episode on public.cineo_playback_clock(episode_id);
create table public.cineo_playback_quality(id uuid primary key,user_id uuid references auth.users(id) on delete set null,episode_id bigint references public.cineo_episodes(id) on delete set null,startup_ms integer not null check(startup_ms between 0 and 300000),stall_count integer not null check(stall_count between 0 and 1000),stall_ms integer not null check(stall_ms between 0 and 14400000),updated_at timestamptz not null default now());
create index cineo_playback_quality_episode on public.cineo_playback_quality(episode_id);
create index cineo_playback_quality_user on public.cineo_playback_quality(user_id);
create table public.cineo_backup_records(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,path text not null,sha256 text not null,summary jsonb not null,created_at timestamptz not null default now());
create index cineo_backup_records_user on public.cineo_backup_records(user_id);
alter table public.cineo_media_jobs add column priority integer not null default 0 check(priority between 0 and 5);
alter table public.cineo_media_jobs add column asset_sha256 text not null default '';
do $$declare t text;begin foreach t in array array['cineo_experience','cineo_library_choices','cineo_bookmarks','cineo_show_info','cineo_episode_notes','cineo_polls','cineo_poll_votes','cineo_receipts','cineo_notices','cineo_surveys','cineo_survey_votes','cineo_staff','cineo_cases','cineo_case_notes','cineo_case_actions','cineo_reason_templates','cineo_revisions','cineo_proposals','cineo_release_news','cineo_feature_flags','cineo_drafts','cineo_playback_clock','cineo_playback_quality','cineo_backup_records']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('cineo-backups','cineo-backups',false,10485760,array['application/octet-stream']) on conflict(id) do nothing;
create function public.cineo_revision_snapshot() returns trigger language plpgsql security invoker set search_path='' as $$begin if old.title is distinct from new.title or old.synopsis is distinct from new.synopsis or old.cover_path is distinct from new.cover_path or old.banner_path is distinct from new.banner_path or old.rating is distinct from new.rating then insert into public.cineo_revisions(show_id,author_id,content) values(old.id,old.owner_id,to_jsonb(old));end if;return new;end$$;
create trigger cineo_revision_snapshot before update on public.cineo_shows for each row execute function public.cineo_revision_snapshot();
revoke all on function public.cineo_revision_snapshot() from public,anon,authenticated;grant execute on function public.cineo_revision_snapshot() to service_role;
create or replace function public.cineo_claim_media() returns setof public.cineo_media_jobs language plpgsql security invoker set search_path='' as $$declare job public.cineo_media_jobs;begin select * into job from public.cineo_media_jobs where status='queued' or(status='processing' and updated_at<now()-interval '30 minutes') order by priority desc,updated_at for update skip locked limit 1;if not found then return;end if;update public.cineo_media_jobs set status='processing',lease=gen_random_uuid(),attempts=attempts+1,updated_at=now() where id=job.id returning * into job;update public.cineo_episodes set media_state='processing' where id=job.episode_id;return next job;end$$;
